export function classifyMaturity(evidence){if(Number(evidence.criticalFailures??0)>0)return'quarantined';const depth=Number(evidence.depthScore??0),pub=Number(evidence.publicScenarios??0),hold=Number(evidence.holdoutScenarios??0),models=Number(evidence.modelFamilies??0),low=Number(evidence.confidenceLowerBound??-Infinity);if(depth>=90&&pub>=50&&hold>=20&&models>=4&&low>0&&evidence.humanReviewed===true&&evidence.productionEvidence===true)return'certified';if(depth>=82&&pub>=20&&hold>=5&&models>=2&&low>0)return'stable';if(depth>=72&&pub>=10&&models>=2&&low>=0)return'validated';if(depth>=60&&pub>=6)return'candidate';return'experimental';}
